-- 이하 전부 RDS 환경 (실서버)
'''
자주 쓰이는 테이블
gbike.rich_user – 유저 정보가 들어있음 (가입시점, 성별, 생년월일, 핸드폰 번호 등)
gbike.rich_orders – 트립 정보가 들어있음 (탑승시간, 종료시간, 거리, 탑승/종료위치 등)
gbike.rich_region – 현재 운영중인 지역목록 데이터 저장되어있음 (소지역, 중지역 …)
gbike.rich_repairs – 정비대기 관련 데이터 (입고시점, 출고시점, QR번호)
gbike.rich_region_auto_move_logs - 지역이동 로그 확인용
gbike_smartops.bicycle_data – 배터리 20%미만 데이터
gbike_smartops.vehicle_statistics_data – 미사용기기 데이터
'''


-- 지역 이동 관련
SELECT date(lo.created_at) as dt, current_region_id, before_region_region_id, count(bicycle_sn) as cnt1,count(distinct lo.bicycle_sn) as cnt2
FROM gbike.rich_region_auto_move_logs lo
where 1=1
-- and bicycle_sn = '390102'
and before_region_region_id = 1168
and date(lo.created_at) BETWEEN '2026-04-01' and '2026-04-02'
group by 1,2,3
limit 10
;

-- 유저 구분값
select
#        case when r.country_code = 'kr' then '내국인' else '외국인' end as country_gubun
        count(r.user_id) as total_user_cnt,
        count(case when r.country_code = 'kr' and r.sign_up_method_type != 'social' then r.user_id end) as mobile_kr_user,
        count(case when r.country_code = 'kr' and r.sign_up_method_type = 'social' then r.user_id end) as social_kr_user,
        count(case when r.country_code != 'kr' and r.sign_up_method_type != 'social' then r.user_id end) as mobile_foreign_user,
        count(case when r.country_code != 'kr' and r.sign_up_method_type = 'social' then r.user_id end) as social_foreign_user,
        count(rs.user_id) as rich_social_table_cnt
from rich_user r
left join rich_social_user rs on rs.user_id = r.user_id
where 1=1
and r.first_order_id is not null -- 한번이라도 탔던 사람
and r.latest_order_id != r.first_order_id ; -- 한번 이상 탄 사람
# and r.sign_up_method_type = 'social'
;

-- 바이크 구분 & 소속 소중대 지역 구분
with region as (
select	r.region_id,
		r.region_name as '소지역',
		rr.region_name as '중지역',
		rrr.region_name as '대지역'
from	gbike.rich_region r
join	gbike.rich_region rr on r.parent_id = rr.region_id
join	gbike.rich_region rrr on rr.parent_id = rrr.region_id
where	1=1
-- and		r.region_id = 764
)
select	rb.bicycle_sn,
		rb.bicycle_id,
		rb.region_id, -- 소지역
		r.`소지역`,
		r.`중지역`,
		r.`대지역`,
		rb.current_speed_mode,
		rb.pre_order_id,
		rb.status,
		CASE
			when rb.type in (15,17,18,22,24) then 'Bicycle'
			when rb.type in (9,10,11,12,13,16,19,23) then 'Scooter'
		else 'none'	END as one_category,
		CASE
			when rb.type = 1 then 'none'
			when rb.type = 2 then 'none'
			when rb.type = 3 then '에어드레서'
			when rb.type = 9 then 'SC_ES4'
			when rb.type = 10 then 'SC_MAX'
			when rb.type = 11 then 'SC_MAX Pro'
			when rb.type = 12 then 'SC_GCOO-K1'
			when rb.type = 13 then 'SC_Max Plus'
			when rb.type = 14 then '슈드레서'
			when rb.type = 15 then 'BI_OMNI bicycle'
			when rb.type = 16 then 'SC_GCOO-K2'
			when rb.type = 17 then 'BI_GCOO-B3'
			when rb.type = 18 then 'BI_GCOO-B2'
			when rb.type = 19 then 'SC_Max Plus X'
			when rb.type = 22 then 'BI_GCOO-B4'
			when rb.type = 23 then 'SC_GCOO-K3'
			when rb.type = 24 then 'BI_A200P'
		else 'none'	END as two_category,
		case when regexp_like(rb.region_name, '임대|파트너') then 1 else 0 end as franchise_yn,
		CONVERT_TZ(FROM_UNIXTIME(rb.add_time),'UTC','Asia/Seoul') as registerd_at,
		CONVERT_TZ(FROM_UNIXTIME(rb.last_used_time),'UTC','Asia/Seoul') as last_used_at,
		rb.speed_mode ->'$.low_speed_limit' AS low_speed,
		rb.speed_mode ->'$.high_speed_limit' AS high_speed
from gbike.rich_bicycle rb 
join region r on rb.region_id = r.region_id
where rb.bicycle_sn = 351239
limit 10;





-- 스쿠터 번호는 테이블 상 bicycle_sn 컬럼으로 검색해야 나옴
-- 그럼 bicycle_id 는? 테이블 조인 키 정도


-- 매출 집계 쿼리
WITH MIDDLE_REGION AS (
    SELECT
        region_id
    FROM
        gbike.rich_region
    WHERE
        country_code = 'th'
      and is_used = 'Y'
      and depth = 2
      and region_name not like '%%X(Don''t use)%%'
),
     LOW_REGION AS (
         SELECT region_id from gbike.rich_region where parent_id IN (select region_id from MIDDLE_REGION)
                                                   and is_used = 'Y'
                                                   and depth = 3
                                                   and region_name not like '%%lostvehicle%%'
                                                   and region_name not like '%%maintenance%%'
                                                   and region_name not like '%%기술기획팀%%'
     )
select
    LEFT(FROM_UNIXTIME(ro.end_time + 7 * 60 * 60),10) as date,
    ro.region_name,
    ro.region_id,
    rbm.name as model,
    SUM(IF(currency_code = 'usd',
           (pay_amount + out_of_area_charge) / 4.5,
           IF(currency_code = 'krw',
              (pay_amount + out_of_area_charge) / 64.545,
              IF(currency_code = 'thb',
                 (pay_amount + out_of_area_charge) / 100,
                 IF(currency_code = 'vnd',
                    (pay_amount + out_of_area_charge) / 1000,
                    IF(currency_code = 'ghs',
                       (pay_amount + out_of_area_charge) / 59.63,
                       0)))))) AS '매출',
    COUNT(ro.order_id) AS '운행수',
    COUNT(DISTINCT ro.bicycle_sn) AS '배치대수'
from
    (select * from gbike.rich_orders where end_time between UNIX_TIMESTAMP(CONVERT_TZ('2025-11-01 00:00:00', 'Asia/Bangkok', 'UTC')) and UNIX_TIMESTAMP(CONVERT_TZ('2025-11-31 23:59:59', 'Asia/Bangkok', 'UTC')) and region_id IN (select region_id from LOW_REGION) and order_state = 2 and is_limit_free = 0 and BINARY country_code = BINARY 'th') as ro
        LEFT JOIN
    gbike.rich_bicycle_models as rbm
    ON
        ro.bicycle_type = rbm.type
group by 1,2,3,4
;


-- 유저 데모
select *,
        case
            when r.age is null then '알수없음'
            when r.age >= 0 and r.age < 10 then '10대 미만'
            when r.age >= 10 and r.age < 20 then '10대'
            when r.age >= 20 and r.age < 30 then '20대'
            when r.age >= 30 and r.age < 40 then '30대'
            when r.age >= 40 and r.age < 50 then '40대'
            when r.age >= 50 and r.age < 60 then '50대'
            when r.age >= 60 and r.age < 70 then '60대'
        else '70대 이상' end as age_group
from (
        select user_id,nickname,region_id,
            CASE 
                WHEN r.gender IS NULL THEN '알 수 없음'
                WHEN MOD(r.gender, 2) = 1 THEN '남자'
                ELSE '여자'
            END AS gender,
            CASE
                WHEN r.birthday IS NULL THEN NULL
                ELSE 
                    FLOOR( 
                        (EXTRACT(YEAR FROM CURRENT_DATE) * 10000 + EXTRACT(MONTH FROM CURRENT_DATE) * 100 + EXTRACT(DAY FROM CURRENT_DATE) 
                        - r.birthday) / 10000
                    )
            END AS age
        from gbike.rich_user r
#         where r.first_order_id is null
) r
