-- 내 개인 마스터 쿼리
with region as ( -- 지역 구분
select	r.region_id,
		r.region_name as '소지역',
		rr.region_name as '중지역',
		rrr.region_name as '대지역'
from	gbike.rich_region r
join	gbike.rich_region rr on r.parent_id = rr.region_id
join	gbike.rich_region rrr on rr.parent_id = rrr.region_id
where	1=1
and		rr.region_name like '원주캠프'
-- and		rrr.region_name = '강남RS팀'
-- and		r.region_id = 223
), bike as ( -- 바이크 구분
select	rb.bicycle_sn,
		rb.bicycle_id,
		rb.region_id, -- 소지역
		rb.current_speed_mode,
		rb.pre_order_id,
		rb.status,
		CASE
			when rb.type in (15,17,18,22,24) then 'Bicycle'
			when rb.type in (9,10,11,12,13,16,19,23) then 'Scooter'
		else 'none'	END as one_category,
		CASE
			when rb.type = 1 then 'none'
			when rb.type = 2 then 'none'
			when rb.type = 3 then '에어드레서'
			when rb.type = 9 then 'SC_ES4'
			when rb.type = 10 then 'SC_MAX'
			when rb.type = 11 then 'SC_MAX Pro'
			when rb.type = 12 then 'SC_GCOO-K1'
			when rb.type = 13 then 'SC_Max Plus'
			when rb.type = 14 then '슈드레서'
			when rb.type = 15 then 'BI_OMNI bicycle'
			when rb.type = 16 then 'SC_GCOO-K2'
			when rb.type = 17 then 'BI_GCOO-B3'
			when rb.type = 18 then 'BI_GCOO-B2'
			when rb.type = 19 then 'SC_Max Plus X'
			when rb.type = 22 then 'BI_GCOO-B4'
			when rb.type = 23 then 'SC_GCOO-K3'
			when rb.type = 24 then 'BI_A200P'
		else 'none'	END as two_category,
		case when regexp_like(rb.region_name, '임대|파트너') then 1 else 0 end as franchise_yn,
		CONVERT_TZ(FROM_UNIXTIME(rb.add_time),'UTC','Asia/Seoul') as registerd_at,
		CONVERT_TZ(FROM_UNIXTIME(rb.last_used_time),'UTC','Asia/Seoul') as last_used_at,
		rb.speed_mode ->'$.low_speed_limit' AS low_speed,
		rb.speed_mode ->'$.high_speed_limit' AS high_speed
from gbike.rich_bicycle rb 
-- where rb.bicycle_sn = 351239
), user as ( -- 유저 구분
select *,
        case
            when r.age is null then '알수없음'
            when r.age >= 10 and r.age < 20 then '10대'
            when r.age >= 20 and r.age < 30 then '20대'
            when r.age >= 30 and r.age < 40 then '30대'
            when r.age >= 40 and r.age < 50 then '40대'
            when r.age >= 50 and r.age < 60 then '50대'
        else '기타' end as age_group
from (
        select user_id,nickname,region_id,
            CASE 
                WHEN r.gender IS NULL THEN null
                WHEN MOD(r.gender, 2) = 1 THEN '남자'
                ELSE '여자'
            END AS gender,
            CASE
                WHEN r.birthday IS NULL THEN NULL
                ELSE 
                    FLOOR( 
                        (EXTRACT(YEAR FROM CURRENT_DATE) * 10000 + EXTRACT(MONTH FROM CURRENT_DATE) * 100 + EXTRACT(DAY FROM CURRENT_DATE) 
                        - r.birthday) / 10000
                    )
            END AS age
        from gbike.rich_user r
) r
)
select	
-- 		r.`대지역`,
-- 		r.`중지역`,
		b.one_category,
		u.gender,u.age_group,
		count(o.order_id) as ord_cnt,
		count(distinct o.bicycle_sn) as bi_cnt,
		count(distinct o.user_id) as user_cnt,
		avg(TIMESTAMPDIFF(SECOND, 
        CONVERT_TZ(FROM_UNIXTIME(o.start_time), 'UTC', 'Asia/Seoul'), 
        CONVERT_TZ(FROM_UNIXTIME(o.end_time), 'UTC', 'Asia/Seoul')
	    ) / 60) AS avg_duration_minutes,
		avg(o.distance) as avg_distace_meter,
		avg(o.unlock_amount) as avg_unlock,
		avg(o.order_amount) as avg_ord_amt,
		avg(o.pay_amount) as avg_pay_amt
FROM                                                                                  
  gbike.rich_orders o
  join region r on o.region_id = r.region_id
  join bike  b on o.bicycle_id = b.bicycle_id
  join user u on u.user_id = o.user_id 
WHERE 1=1                                                                                
  and o.order_state = 2                                                               
  AND o.add_time BETWEEN UNIX_TIMESTAMP(CONVERT_TZ('2026-04-01 00:00:00', 'Asia/Seoul', 'UTC')) 
  AND UNIX_TIMESTAMP(CONVERT_TZ('2026-04-13 23:59:59', 'Asia/Seoul', 'UTC'))
--   and O.bicycle_id  = 73344 -- bicycle_sn 390102
--   and O.region_id = 1168
  and u.age_group not in ('알수없음')
  and u.gender is not null
group by 1,2,3
;

-- 제니퍼 쿼리
WITH base AS (
    SELECT
        O.user_id,
        CASE 
            WHEN CONVERT_TZ(FROM_UNIXTIME(O.add_time), 'UTC', 'Asia/Seoul') 
                 BETWEEN '2025-01-01' AND '2025-04-13 23:59:59' THEN '작년'
            WHEN CONVERT_TZ(FROM_UNIXTIME(O.add_time), 'UTC', 'Asia/Seoul') 
                 BETWEEN '2026-01-01' AND '2026-04-13 23:59:59' THEN '올해'
        END AS year_type,
        CASE 
            WHEN O.bicycle_type IN (15,17,18,22,24) THEN '자전거'
            ELSE '킥보드'
        END AS device_type,
        CASE 
            WHEN U.gender IN (0,2,4,6,8) THEN '여성'
            WHEN U.gender IN (1,3,5,7,9) THEN '남성'
            ELSE '기타'
        END AS gender,
        FLOOR(
            TIMESTAMPDIFF(
                YEAR,
                STR_TO_DATE(U.birthday, '%Y%m%d'),
                CONVERT_TZ(FROM_UNIXTIME(O.add_time), 'UTC', 'Asia/Seoul')
            )
        ) AS age,
        (O.end_time - O.start_time) AS ride_time
    FROM gbike.rich_orders O
    JOIN gbike.rich_user U 
        ON O.user_id = U.user_id
    WHERE
        O.order_state = 2
        AND O.region_id IN (568, 573, 575)
        AND (
            CONVERT_TZ(FROM_UNIXTIME(O.add_time), 'UTC', 'Asia/Seoul') 
                BETWEEN '2025-01-01' AND '2025-04-13 23:59:59'
            OR
            CONVERT_TZ(FROM_UNIXTIME(O.add_time), 'UTC', 'Asia/Seoul') 
                BETWEEN '2026-01-01' AND '2026-04-13 23:59:59'
        )
),
age_grouped AS (
    SELECT *,
        CASE 
            WHEN age BETWEEN 10 AND 19 THEN '10대'
            WHEN age BETWEEN 20 AND 29 THEN '20대'
            WHEN age BETWEEN 30 AND 39 THEN '30대'
            WHEN age BETWEEN 40 AND 49 THEN '40대'
            WHEN age BETWEEN 50 AND 59 THEN '50대'
            ELSE '기타'
        END AS age_group
    FROM base
    WHERE year_type IS NOT NULL
),
user_ride_count AS (
    SELECT
        year_type,
        device_type,
        gender,
        age_group,
        user_id,
        COUNT(*) AS ride_cnt,
        SUM(CASE WHEN ride_time < 300 THEN 1 ELSE 0 END) AS short_ride_cnt,
        SUM(CASE WHEN ride_time < 180 THEN 1 ELSE 0 END) AS very_short_ride_cnt
    FROM age_grouped
    GROUP BY 1,2,3,4,5
)
SELECT
    year_type AS `연도 구분`,
    device_type AS `기종`,
    gender AS `성별`,
    age_group AS `연령대`,
    SUM(ride_cnt) AS `운행수`,
    COUNT(DISTINCT user_id) AS `탑승회원수`,
    COUNT(DISTINCT CASE WHEN ride_cnt >= 30 THEN user_id END) AS `주 2회 이상`,
    COUNT(DISTINCT CASE WHEN ride_cnt >= 60 THEN user_id END) AS `주 4회 이상`,
    COUNT(DISTINCT CASE WHEN ride_cnt >= 105 THEN user_id END) AS `주 7회 이상`,
    SUM(very_short_ride_cnt) AS `3분 미만 운행수`,
    SUM(short_ride_cnt) AS `5분 미만 운행수`
FROM user_ride_count
GROUP BY 1,2,3,4
ORDER BY 1,2,3,4
;




-- 구독자 비구독자 트립 횟수 월별 비교
WITH user_categories AS (    
SELECT ru.user_id, 
    FROM_UNIXTIME(ru.add_time, '%Y-%m') as month,
    CASE
    WHEN COUNT(DISTINCT CASE WHEN rb.is_subscribe = 1 THEN rbo.user_id END) > 0 THEN 'subscription_user'
    WHEN COUNT(DISTINCT CASE WHEN rb.is_subscribe = 0 THEN rbo.user_id END) > 0 THEN 'product_user'
    ELSE 'non_purchase_user'
    END as user_category
FROM rich_user ru    
LEFT JOIN rich_coupon c ON ru.user_id = c.user_id         
                        AND c.add_time BETWEEN ru.add_time AND ru.add_time + (90  24  3600)        
                        AND c.order_id > 0        
                        AND c.coupon_type IN (1, 3)    
LEFT JOIN rich_booster_coupons b ON c.coupon_id = b.coupon_id    
LEFT JOIN rich_booster_orders rbo ON b.booster_order_id = rbo.id    
LEFT JOIN rich_boosters rb ON rbo.booster_id = rb.id    
WHERE ru.user_id > 5406445
AND ru.add_time >= UNIX_TIMESTAMP('2025-07-01 00:00:00') - 96060     
GROUP BY ru.user_id, FROM_UNIXTIME(ru.add_time, '%Y-%m')
), user_trips AS 
(
    SELECT uc.user_id, uc.month, uc.user_category,COUNT(ro.order_id) as trip_count    
    FROM user_categories uc    
    LEFT JOIN rich_orders ro ON uc.user_id = ro.user_id        
    AND ro.order_state = 2  -- 완료된 주문만        
    AND ro.is_limit_free = 0        
    AND ro.order_id > 215997914        
    AND ro.add_time >= UNIX_TIMESTAMP('2025-07-01 00:00:00') - 96060    
    GROUP BY uc.user_id, uc.month, uc.user_category 
) 
SELECT  ut.month,    
        COUNT(DISTINCT CASE WHEN ut.user_category = 'subscription_user' THEN ut.user_id END) as '구독 상품 구매 유저 수',    
        ROUND(AVG(CASE WHEN ut.user_category = 'subscription_user' THEN ut.trip_count END), 2) as '구독 유저 평균 트립수',    
        COUNT(DISTINCT CASE WHEN ut.user_category = 'product_user' THEN ut.user_id END) as '일반 상품 구매 유저 수',    
        ROUND(AVG(CASE WHEN ut.user_category = 'product_user' THEN ut.trip_count END), 2) as '일반 상품 유저 평균 트립수',    
        COUNT(DISTINCT CASE WHEN ut.user_category = 'non_purchase_user' THEN ut.user_id END) as '비구매 유저 수',    
        ROUND(AVG(CASE WHEN ut.user_category = 'non_purchase_user' THEN ut.trip_count END), 2) as '비구매 유저 평균 트립수' 
FROM user_trips ut GROUP BY ut.month ORDER BY ut.month
;




WITH monthly_subscribers AS (    -- 월별 구독자 (중복 제거)    
    SELECT bo.user_id,b.title,DATE_FORMAT(date_add(bo.created_at, interval 9 hour), '%Y-%m') as 구매월    
    FROM gbike.rich_boosters as b        
    join gbike.rich_booster_orders as bo on bo.booster_id = b.id    
    WHERE booster_id in (168,169,170)        
    and bo.price is not null    
    GROUP BY bo.user_id, b.title, DATE_FORMAT(date_add(bo.created_at, interval 9 hour), '%Y-%m') 
), subscription_flow AS (    -- 구독 흐름 분석    
    SELECT  curr.구매월,curr.title,curr.user_id,prev.구매월 as 전월구독여부,next_month.구매월 as 다음월구독여부,        
    -- 이번달 구독 상태 (전월 대비)        
            CASE  
                WHEN prev.구매월 IS NULL THEN '신규구독'            
                WHEN DATE_ADD(STR_TO_DATE(CONCAT(prev.구매월, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) = STR_TO_DATE(CONCAT(curr.구매월, '-01'), '%Y-%m-%d') THEN '유지구독'
            ELSE '재구독' END as 구독상태,        
    -- 다음달 상태 (해지 여부 확인용)        
            CASE            
                WHEN next_month.구매월 IS NULL THEN '해지'            
                WHEN DATE_ADD(STR_TO_DATE(CONCAT(curr.구매월, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) = STR_TO_DATE(CONCAT(next_month.구매월, '-01'), '%Y-%m-%d') THEN '유지'            
            ELSE '일시중단' END as 다음달상태    
    FROM monthly_subscribers curr    
    LEFT JOIN monthly_subscribers prev ON curr.user_id = prev.user_id        
                                        AND curr.title = prev.title        
                                        AND DATE_ADD(STR_TO_DATE(CONCAT(prev.구매월, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) = STR_TO_DATE(CONCAT(curr.구매월, '-01'), '%Y-%m-%d')
    LEFT JOIN monthly_subscribers next_month ON curr.user_id = next_month.user_id 
                                        AND curr.title = next_month.title        
                                        AND DATE_ADD(STR_TO_DATE(CONCAT(curr.구매월, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) = STR_TO_DATE(CONCAT(next_month.구매월, '-01'), '%Y-%m-%d') 
)
-- 최종 통합 집계 
SELECT    구매월,    title as 상품명, -- 이번달 구독 현황 (과거→현재) 
COUNT(CASE WHEN 구독상태 = '신규구독' THEN user_id END) as 신규구독자수, 
COUNT(CASE WHEN 구독상태 = '유지구독' THEN user_id END) as 유지구독자수, 
COUNT(user_id) as 이번달총구독자수,
-- 해지 분석 (현재→미래, 실제로는 과거 데이터 기반) 
COUNT(CASE WHEN 다음달상태 = '해지' THEN user_id END) as 해지자수, 
COUNT(CASE WHEN 다음달상태 = '유지' THEN user_id END) as 다음달유지자수,
-- 비율 계산 
ROUND((COUNT(CASE WHEN 다음달상태 = '해지' THEN user_id END) / COUNT(user_id))  100, 2) as 해지율, 
ROUND((COUNT(CASE WHEN 다음달상태 = '유지' THEN user_id END) / COUNT(user_id))  100, 2) as 유지율
FROM subscription_flow 
GROUP BY 구매월, title 
ORDER BY 구매월 DESC, title
;






-- 소지역별 평균 탑승 시간
with region as ( -- 지역 구분
select	r.region_id,
		r.region_name as '소지역',
		rr.region_name as '중지역',
		rrr.region_name as '대지역'
from	gbike.rich_region r
join	gbike.rich_region rr on r.parent_id = rr.region_id
join	gbike.rich_region rrr on rr.parent_id = rrr.region_id
where	1=1
and		rr.region_name like '원주캠프'
), bike as ( -- 바이크 구분
select	rb.bicycle_sn,
		rb.bicycle_id,
		rb.region_id, -- 소지역
		rb.current_speed_mode,
		rb.pre_order_id,
		rb.status,
		CASE
			when rb.type in (15,17,18,22,24) then 'Bicycle'
			when rb.type in (9,10,11,12,13,16,19,23) then 'Scooter'
		else 'none'	END as one_category,
		CASE
			when rb.type = 1 then 'none'
			when rb.type = 2 then 'none'
			when rb.type = 3 then '에어드레서'
			when rb.type = 9 then 'SC_ES4'
			when rb.type = 10 then 'SC_MAX'
			when rb.type = 11 then 'SC_MAX Pro'
			when rb.type = 12 then 'SC_GCOO-K1'
			when rb.type = 13 then 'SC_Max Plus'
			when rb.type = 14 then '슈드레서'
			when rb.type = 15 then 'BI_OMNI bicycle'
			when rb.type = 16 then 'SC_GCOO-K2'
			when rb.type = 17 then 'BI_GCOO-B3'
			when rb.type = 18 then 'BI_GCOO-B2'
			when rb.type = 19 then 'SC_Max Plus X'
			when rb.type = 22 then 'BI_GCOO-B4'
			when rb.type = 23 then 'SC_GCOO-K3'
			when rb.type = 24 then 'BI_A200P'
		else 'none'	END as two_category,
		case when regexp_like(rb.region_name, '임대|파트너') then 1 else 0 end as franchise_yn,
		CONVERT_TZ(FROM_UNIXTIME(rb.add_time),'UTC','Asia/Seoul') as registerd_at,
		CONVERT_TZ(FROM_UNIXTIME(rb.last_used_time),'UTC','Asia/Seoul') as last_used_at,
		rb.speed_mode ->'$.low_speed_limit' AS low_speed,
		rb.speed_mode ->'$.high_speed_limit' AS high_speed
from gbike.rich_bicycle rb
)
select
#         date(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul')) as dt,
        DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul'),'%Y-W%v') as weeknum,
		r.`대지역`,
		r.`중지역`,
		r.`소지역`,
		b.one_category as `기종구분`,
		count(o.order_id) as `트립수`,
		count(distinct o.bicycle_sn) as '운행된 기종수_중복제거',
		count(distinct o.user_id) as '이용한 유저 수_중복제거',
		avg(TIMESTAMPDIFF(SECOND,
        CONVERT_TZ(FROM_UNIXTIME(o.start_time), 'UTC', 'Asia/Seoul'),
        CONVERT_TZ(FROM_UNIXTIME(o.end_time), 'UTC', 'Asia/Seoul')
	    ) / 60) AS '평균탑승시간(분)',
		avg(o.distance) as '평균탑승거리(meter)',
		avg(o.unlock_amount) as '평균언락비용',
		avg(o.order_amount) as '평균주문금액',
		avg(o.pay_amount) as '평균결제금액'
FROM
  gbike.rich_orders o
  join region r on o.region_id = r.region_id
  join bike  b on o.bicycle_id = b.bicycle_id
WHERE 1=1
  and o.order_state = 2
  AND o.add_time BETWEEN UNIX_TIMESTAMP(CONVERT_TZ('2026-04-13 00:00:00', 'Asia/Seoul', 'UTC'))
  AND UNIX_TIMESTAMP(CONVERT_TZ('2026-04-19 23:59:59', 'Asia/Seoul', 'UTC'))
group by
#         date(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul')),
        DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul'),'%Y-W%v'),
		r.`대지역`,
		r.`중지역`,
		r.`소지역`,
		b.one_category
;


