            date_add(d.deployed_at, interval 9 hour) as deployed_at,
            date_add(d.released_at, interval 9 hour) as released_at
    FROM gbike.rich_deploy_zone_usages d
            JOIN
        gbike.rich_release_spot s ON d.deploy_zone_id = s.id
