    )
group by o.from_api, CASE o.bicycle_type
                WHEN 1 THEN 'GCOO-B1' WHEN 2 THEN 'UNKNOWN' WHEN 3 THEN '에어드레서'
                WHEN 9 THEN 'ES4' WHEN 10 THEN 'Max' WHEN 11 THEN 'Max Pro'
                WHEN 12 THEN 'GCOO-K1' WHEN 13 THEN 'Max Plus' WHEN 14 THEN '슈드레서'
                WHEN 15 THEN 'OMNI BICYCLE' WHEN 16 THEN 'GCOO-K2' WHEN 17 THEN 'GCOO-B3'
                WHEN 18 THEN 'GCOO-B2' WHEN 19 THEN 'Max Plus X' WHEN 22 THEN 'GCOO-B4'
                WHEN 23 THEN 'GCOO-K3' WHEN 24 THEN 'A200P'
                ELSE CONCAT('기타(', IFNULL(o.bicycle_type, 'NULL'), ')')
            END
;


-- 케플러 자료 뽑기
SELECT /*+ JOIN_ORDER(r, rr, rrr, o, rb) INDEX(o IDX_SALES)
         46초 소요 */
    rrr.region_name as '대지역',
    rr.region_name  as '중지역',
    r.region_name   as '소지역',
    rb.bicycle_sn,
    CASE
        WHEN rb.type IN (15, 17, 18, 22, 24) THEN 'Bicycle'
        WHEN rb.type IN (9, 10, 11, 12, 13, 16, 19, 23) THEN 'Scooter'
        ELSE 'none'
    END AS one_category,
    CASE
        WHEN rb.type = 3 THEN '에어드레서'
        WHEN rb.type = 9 THEN 'SC_ES4'
        WHEN rb.type = 10 THEN 'SC_MAX'
        WHEN rb.type = 11 THEN 'SC_MAX Pro'
        WHEN rb.type = 12 THEN 'SC_GCOO-K1'
        WHEN rb.type = 13 THEN 'SC_Max Plus'
        WHEN rb.type = 14 THEN '슈드레서'
        WHEN rb.type = 15 THEN 'BI_OMNI bicycle'
        WHEN rb.type = 16 THEN 'SC_GCOO-K2'
        WHEN rb.type = 17 THEN 'BI_GCOO-B3'
        WHEN rb.type = 18 THEN 'BI_GCOO-B2'
        WHEN rb.type = 19 THEN 'SC_Max Plus X'
        WHEN rb.type = 22 THEN 'BI_GCOO-B4'
        WHEN rb.type = 23 THEN 'SC_GCOO-K3'
        WHEN rb.type = 24 THEN 'BI_A200P'
        ELSE 'none'
    END AS two_category,
    CONVERT_TZ(FROM_UNIXTIME(o.start_time), 'UTC', 'Asia/Seoul') as start_time,
    CONVERT_TZ(FROM_UNIXTIME(o.end_time), 'UTC', 'Asia/Seoul') as end_time,
    TIMESTAMPDIFF(SECOND,
        FROM_UNIXTIME(o.start_time),
        FROM_UNIXTIME(o.end_time)
    ) / 60 AS riding_duration_minutes,
    o.distance as distance_meter,
    ST_X(start_point) as `출발지 경도`, -- ST_LONGITUDE 대신 ST_X 사용 가능 (버전 확인 필요)
    ST_Y(start_point) as `출발지 위도`,
    ST_X(end_point) as `도착지 경도`,
    ST_Y(end_point) as `도착지 위도`,
    POINT(
        ST_LONGITUDE(start_point),
        ST_LATITUDE(start_point)
    ) AS start_geo,
    POINT(
        ST_LONGITUDE(end_point),
        ST_LATITUDE(end_point)
    ) AS end_geo
FROM gbike.rich_orders o
JOIN gbike.rich_region r ON o.region_id = r.region_id
JOIN gbike.rich_region rr ON r.parent_id = rr.region_id
JOIN gbike.rich_region rrr ON rr.parent_id = rrr.region_id
JOIN gbike.rich_bicycle rb ON o.bicycle_id = rb.bicycle_id
WHERE o.order_state = 2
  AND o.add_time BETWEEN UNIX_TIMESTAMP(CONVERT_TZ('2026-04-01 00:00:00', 'Asia/Seoul', 'UTC'))
                     AND UNIX_TIMESTAMP(CONVERT_TZ('2026-04-28 23:59:59', 'Asia/Seoul', 'UTC'))
  AND rr.region_name = '대전2캠프'
;

-- 배치존 위치 뽑기
with region as ( -- 지역 구분
    select r.region_id,
           r.region_name   as '소지역',
           rr.region_name  as '중지역',
           rrr.region_name as '대지역'
    from gbike.rich_region r
             join gbike.rich_region rr on r.parent_id = rr.region_id
             join gbike.rich_region rrr on rr.parent_id = rrr.region_id
    where 1 = 1
      and rr.region_name like '대전2캠프'
    )
select  r.중지역,r.소지역,
        s.id as deploy_zone_id,
        s.name                                   as '배치존명',
        s.lng as `배치존 경도`,s.lat as `배치존 위도`,
        s.location,s.updated_at,s.created_at
FROM gbike.rich_deploy_zone_usages d
        JOIN
    gbike.rich_release_spot s ON d.deploy_zone_id = s.id
        JOIN
    region r ON s.region_id = r.region_id
where 1=1
;

-- 이상 유저 탐지 _ 도착 포인트와 다음 시작 포인트가 100미터 이상 차이나는 건수 기준
WITH ordered AS (
    SELECT
        O.user_id,
        O.bicycle_sn,
        O.add_time,
        DATE_FORMAT(FROM_UNIXTIME(O.add_time + 32400), '%Y-%m') AS ym,
        O.end_point AS end_geo,
        LEAD(O.start_point) OVER (
            PARTITION BY O.bicycle_sn
            ORDER BY O.add_time
        ) AS next_start_geo,
        E.region_name
    FROM gbike.rich_orders O # use index (IDX_SALES)
    JOIN gbike.rich_region R ON O.region_id = R.region_id
    JOIN gbike.rich_region E ON R.parent_id = E.region_id
    WHERE O.order_state = 2
      AND E.region_name = '서초캠프'
      AND O.add_time BETWEEN UNIX_TIMESTAMP('2026-04-01 00:00:00') - 9*3600
                           AND UNIX_TIMESTAMP('2026-04-28 23:59:59') - 9*3600
      AND O.bicycle_type IN (15, 17, 18, 22, 24)
),
abnormal AS (
    SELECT user_id, ym, region_name
    FROM (
        SELECT user_id, ym, region_name, ST_Distance_Sphere(end_geo, next_start_geo) AS dist_m
        FROM ordered
        WHERE next_start_geo IS NOT NULL
    ) t
    WHERE dist_m >= 100
),
heavy_users AS (
    SELECT user_id
    FROM abnormal
    GROUP BY user_id
    HAVING COUNT(*) >= 10
)
SELECT ym, region_name,COUNT(*) AS monthly_abnormal_count
FROM abnormal
WHERE user_id IN (SELECT user_id FROM heavy_users)
GROUP BY ym, region_name
ORDER BY ym;


-- 배치존 출루 or 일반 출루 구분값
SELECT
    ST_X(rich_orders.start_point) AS latitude,
    ST_Y(rich_orders.start_point) AS longitude,
    CASE
        WHEN rich_deploy_zone_usages.id IS NULL THEN 'out_of_release_spot'
        ELSE 'in_release_spot'
        END AS spot_type
FROM rich_orders
         JOIN rich_deploy_zone_usages
                   ON  rich_orders.order_id = rich_deploy_zone_usages.trip_id
WHERE
   rich_orders.add_time BETWEEN $__unixEpochFrom() AND $__unixEpochTo()
   AND rich_orders.region_id IN (${Region:csv})
;

# 할인 지쿠 성과 검증용 데이터
SELECT
    (select region_name from rich_region where rich_discount_scooter_experiment_logs.region_id=rich_region.region_id )as region_name,
    DATE_FORMAT(created_at, '%Y-%m-%d %H:00:00') AS hour,
    COUNT(*) AS count,
    GROUP_CONCAT(' ', bicycle_sn) AS bicycle_sns,
    is_discount
FROM
    rich_discount_scooter_experiment_logs
GROUP BY
    region_id, hour, is_discount
ORDER BY
    region_id, hour
;


# 대시보드용 배치 쿼리
WITH DAILY_TABLE_PM_TYPE AS	(SELECT
		gbike.rich_orders.*, ceil((end_time - start_time)/60) AS use_time, m.model_type AS pm_type
	FROM
		gbike.rich_orders
	JOIN
		rich_bicycle b
	ON
		rich_orders.bicycle_id = b.bicycle_id
	JOIN
		rich_bicycle_models m
	ON
		b.type = m.type
	WHERE
		order_id >=
		(SELECT
			MIN(order_id)
		FROM
			gbike.rich_orders
		WHERE
			rich_orders.add_time > (SELECT UNIX_TIMESTAMP(DATE_SUB(DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY), INTERVAL 1 MONTH)) + 9*60*60 )

		) AND
        order_id <
		(SELECT
			MIN(order_id)
		FROM
			gbike.rich_orders
		WHERE
			rich_orders.add_time >= (SELECT UNIX_TIMESTAMP(LAST_DAY(DATE_SUB(CURDATE(), INTERVAL 1 MONTH))) + 33*60*60)
		)
	)
SELECT
	*
FROM
(SELECT
	# 월별
	DATE_FORMAT(FROM_UNIXTIME(DAILY_TABLE_PM_TYPE.add_time-9*60*60), '%Y-%m-%d') AS "day",
	# 탑승수
	COUNT(*) AS ride_cnt,
	# max order_id
	MAX(order_id) AS max_order_id,
	# Riders(MAU)
	COUNT(DISTINCT user_id) AS mau,
	# 쿠폰포함 매출
	SUM(order_amount + out_of_area_charge - refund_amount-refund_out_of_area_charge) AS sales_w_coupon,
	# 쿠폰제외 매출
	SUM(pay_amount + out_of_area_charge - refund_amount-refund_out_of_area_charge) AS sales_wo_coupon,
	# 사용된스쿠터수
	COUNT(DISTINCT bicycle_sn) AS used_bicycle_cnt,
	# 탑승시간
	ceil(SUM(end_time - start_time)/60) AS trip_time_sum
FROM
	DAILY_TABLE_PM_TYPE
WHERE
	order_state = 2 # 정상적으로 탑승이 일어난 order
	AND country_code = "kr" # 국가코드 = kr
	AND pm_type = "bicycle" #pm_type, 해당 줄 주석처리 시 전체 ["bicycle", "scooter"]
GROUP BY
	day ) AS DAILY_STAT
JOIN
    (SELECT
	# 일자별
	DATE_FORMAT(rich_channeling_day_sales_statistics.date, '%Y-%m-%d') AS "DAY",
    # REVENUE
	SUM(pay_amount - CASE
                            WHEN (from_api = 'kakaot')
                                THEN ROUND((order_amount + return_amount) * 0.1)
                            WHEN (from_api = 'tmap')
                                THEN FLOOR((order_amount + return_amount) * 0.099)
                            WHEN (from_api = 'shucle')
                                THEN FLOOR((order_amount + return_amount) * 0.08)
                            WHEN (from_api = 'tmoney')
                                THEN FLOOR((order_amount + return_amount) * 0.085)
                            WHEN (from_api = 'toss')
                                THEN FLOOR((order_amount + return_amount) * 0.0913)
                            WHEN (from_api = 'kmaas')
                                THEN FLOOR((order_amount + return_amount) * 0.0275)
                            WHEN (from_api = 'hwikgo')
                                THEN FLOOR((order_amount + return_amount) * 0.019)
                            ELSE 0
		END
		- (refund_order_amount + refund_return_amount + refund_credit)
			   ) AS revenue
	FROM gbike.rich_channeling_day_sales_statistics
			 JOIN gbike.rich_region ON rich_channeling_day_sales_statistics.region_id = rich_region.region_id
			 JOIN gbike.rich_bicycle_models ON rich_channeling_day_sales_statistics.bicycle_type = rich_bicycle_models.type
	WHERE date BETWEEN
		DATE_SUB(DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY), INTERVAL 1 MONTH) AND
		LAST_DAY(DATE_SUB(CURDATE(), INTERVAL 1 MONTH)) # 저번달
		AND rich_region.country_code = 'kr'
		AND rich_bicycle_models.model_type = "bicycle" #pm_type, 해당 줄 주석처리 시 전체 ["bicycle", "scooter"]
	GROUP BY
		DAY) AS DAILY_REVENUE
ON
    DAILY_STAT.day = DAILY_REVENUE.DAY;


# 제주 지역 외부 이용객 비중 파악
with region as ( -- 지역 구분
    select	r.region_id,
            r.region_name as '소지역',
            rr.region_name as '중지역',
            rrr.region_name as '대지역',r.country_code
    from	gbike.rich_region r
    join	gbike.rich_region rr on r.parent_id = rr.region_id
    join	gbike.rich_region rrr on rr.parent_id = rrr.region_id
    where	1=1
#     and		rr.region_name like '원주캠프'
    -- and		rrr.region_name = '강남RS팀'
    -- and		r.region_id = 223
), bike as ( -- 바이크 구분
    select	rb.bicycle_sn,
            rb.bicycle_id,
            rb.region_id, -- 소지역
            rb.current_speed_mode,
            rb.pre_order_id,
            rb.status,
            CASE
                when rb.type in (15,17,18,22,24) then 'Bicycle'
                when rb.type in (9,10,11,12,13,16,19,23) then 'Scooter'
            else 'none'	END as one_category,
            CASE
                when rb.type = 1 then 'none'
                when rb.type = 2 then 'none'
                when rb.type = 3 then '에어드레서'
                when rb.type = 9 then 'SC_ES4'
                when rb.type = 10 then 'SC_MAX'
                when rb.type = 11 then 'SC_MAX Pro'
                when rb.type = 12 then 'SC_GCOO-K1'
                when rb.type = 13 then 'SC_Max Plus'
                when rb.type = 14 then '슈드레서'
                when rb.type = 15 then 'BI_OMNI bicycle'
                when rb.type = 16 then 'SC_GCOO-K2'
                when rb.type = 17 then 'BI_GCOO-B3'
                when rb.type = 18 then 'BI_GCOO-B2'
                when rb.type = 19 then 'SC_Max Plus X'
                when rb.type = 22 then 'BI_GCOO-B4'
                when rb.type = 23 then 'SC_GCOO-K3'
                when rb.type = 24 then 'BI_A200P'
            else 'none'	END as two_category
#             case when regexp_like(rb.region_name, '임대|파트너') then 1 else 0 end as franchise_yn,
#             CONVERT_TZ(FROM_UNIXTIME(rb.add_time),'UTC','Asia/Seoul') as registerd_at,
#             CONVERT_TZ(FROM_UNIXTIME(rb.last_used_time),'UTC','Asia/Seoul') as last_used_at,
#             rb.speed_mode ->'$.low_speed_limit' AS low_speed,
#             rb.speed_mode ->'$.high_speed_limit' AS high_speed
    from gbike.rich_bicycle rb
    -- where rb.bicycle_sn = 351239
), user as ( -- 유저 구분
    select r.*,
            case
                when r.age is null then 'unknown'
                when r.age >= 10 and r.age < 20 then '10대'
                when r.age >= 20 and r.age < 30 then '20대'
                when r.age >= 30 and r.age < 40 then '30대'
                when r.age >= 40 and r.age < 50 then '40대'
                when r.age >= 50 and r.age < 60 then '50대'
            else '기타' end as age_group,
            case when rr.중지역 = '제주캠프' then '제주 가입자' else '타지역 가입자' end as regist_gubun,
            case when r.country_code = 'kr' then '내국인' else '외국인' end as country_gubun
    from (
            select user_id,nickname,region_id,
                CASE
                    WHEN r.gender IS NULL THEN 'unknown'
                    WHEN MOD(r.gender, 2) = 1 THEN '남자'
                    ELSE '여자'
                END AS gender,
                CASE
                    WHEN r.birthday IS NULL THEN NULL
                    ELSE
                        FLOOR(
                            (EXTRACT(YEAR FROM CURRENT_DATE) * 10000 + EXTRACT(MONTH FROM CURRENT_DATE) * 100 + EXTRACT(DAY FROM CURRENT_DATE)
                            - r.birthday) / 10000
                        )
                END AS age,
                r.country_code
            from gbike.rich_user r
    ) r
    join region rr on r.region_id = rr.region_id
)
select
        date(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul')) as dt,
        DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul'),'%Y-%m') as month,
		r.`대지역`,
		r.`중지역`,
		r.`소지역`,
		b.one_category,
		u.gender,u.age_group,
        u.regist_gubun,u.country_gubun,
		count(o.order_id) as `트립수`,
		count(distinct o.bicycle_sn) as `운행기기수_중복제거`,
		count(distinct o.user_id) as `유저수_중복제거`,
		sum(TIMESTAMPDIFF(SECOND,
        CONVERT_TZ(FROM_UNIXTIME(o.start_time), 'UTC', 'Asia/Seoul'),
        CONVERT_TZ(FROM_UNIXTIME(o.end_time), 'UTC', 'Asia/Seoul')
	    ) / 60) AS `합계운행시간(분)`,
		sum(o.distance) as `합계운행거리(meter)`,
		sum(o.order_amount) as `합계주문금액`,
		sum(o.pay_amount) as `합계결제금액`
FROM
  gbike.rich_orders o # use index (IDX_SALES)
  join region r on o.region_id = r.region_id
  join bike  b on o.bicycle_id = b.bicycle_id
  join user u on u.user_id = o.user_id
WHERE 1=1
  and o.order_state = 2
  AND o.add_time BETWEEN UNIX_TIMESTAMP(CONVERT_TZ('2026-04-01 00:00:00', 'Asia/Seoul', 'UTC'))
  AND UNIX_TIMESTAMP(CONVERT_TZ('2026-04-30 23:59:59', 'Asia/Seoul', 'UTC'))
#   and u.age_group not in ('알수없음')
#   and u.gender is not null
  and r.중지역 = '제주캠프'
group by
        date(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul')),
        DATE_FORMAT(CONVERT_TZ(FROM_UNIXTIME(o.add_time), 'UTC', 'Asia/Seoul'),'%Y-%m'),
		r.`대지역`,
		r.`중지역`,
		r.`소지역`,
		b.one_category,
		u.gender,u.age_group,
        u.regist_gubun,u.country_gubun
;




-- 이거 안나옴
WITH user_jf_last_order AS (
    -- 1~2월 각 유저별 마지막 탑승건(최대 order_id) 추출
    SELECT
        user_id,
        MAX(order_id) AS last_order_id
    FROM gbike.rich_orders
    WHERE add_time >= UNIX_TIMESTAMP('2026-01-01 00:00:00') - 32400
      AND add_time < UNIX_TIMESTAMP('2026-03-01 00:00:00') - 32400
      AND order_state = 2 -- 완료된 유효 탑승 건만 집계
    GROUP BY user_id
),
target_users AS (
    -- 마지막 탑승건이 타겟 캠프인 유저 필터링
    SELECT
        U.user_id,
        E.region_name AS camp_name
    FROM user_jf_last_order U
    JOIN gbike.rich_orders O ON U.last_order_id = O.order_id
    JOIN gbike.rich_region R ON O.region_id = R.region_id
    JOIN gbike.rich_region E ON R.parent_id = E.region_id
    WHERE E.region_name IN ('서초캠프', '광주1캠프', '평택캠프', '용인캠프')
),
mar_apr_riders AS (
    -- 3~4월 탑승 이력이 있는 유저 풀 (타겟 유저를 내부 조인하여 스캔 범위 최소화)
    SELECT DISTINCT O.user_id
    FROM gbike.rich_orders O
    JOIN target_users T ON O.user_id = T.user_id
    WHERE O.add_time >= UNIX_TIMESTAMP('2026-03-01 00:00:00') - 32400
      AND O.add_time < UNIX_TIMESTAMP('2026-05-01 00:00:00') - 32400
      AND O.order_state = 2
)
-- 스케일링
SELECT
    T.camp_name,
    COUNT(T.user_id) AS no_mar_apr_ride_users
FROM target_users T
LEFT JOIN mar_apr_riders M ON T.user_id = M.user_id
WHERE M.user_id IS NULL
GROUP BY T.camp_name
;



-- 캠프별 유저 세그먼트 수
WITH user_agg AS (
    -- 3~4월 데이터를 단 1번만 스캔하여 (Index 활용) 필요한 모든 지표를 동시 집계
    SELECT 
        user_id,
        -- 3월 탑승 횟수
        COUNT(CASE WHEN add_time >= UNIX_TIMESTAMP('2026-03-01 00:00:00') - 32400 
                    AND add_time <  UNIX_TIMESTAMP('2026-04-01 00:00:00') - 32400 
                   THEN order_id END) AS march_ride_count,
        -- 4월 탑승 횟수
        COUNT(CASE WHEN add_time >= UNIX_TIMESTAMP('2026-04-01 00:00:00') - 32400 
                    AND add_time <  UNIX_TIMESTAMP('2026-05-01 00:00:00') - 32400 
                   THEN order_id END) AS apr_ride_count,
        -- 4월 마지막 탑승건 (ROW_NUMBER 정렬을 대체하는 PK MAX 활용)
        MAX(CASE WHEN add_time >= UNIX_TIMESTAMP('2026-04-01 00:00:00') - 32400 
                  AND add_time <  UNIX_TIMESTAMP('2026-05-01 00:00:00') - 32400 
                 THEN order_id END) AS max_apr_order_id
    FROM gbike.rich_orders
    WHERE add_time >= UNIX_TIMESTAMP('2026-03-01 00:00:00') - 32400
      AND add_time <  UNIX_TIMESTAMP('2026-05-01 00:00:00') - 32400
      AND order_state = 2 -- 완료된 유효 탑승 건만
    GROUP BY user_id
),
target_users AS (
    -- 4월 탑승 이력이 존재하면서, 그 마지막 탑승 지역이 타겟 캠프인 유저만 필터링
    SELECT 
        U.user_id,
        U.apr_ride_count,
        U.march_ride_count,
        E.region_name AS camp_name
    FROM user_agg U
    JOIN gbike.rich_orders O ON U.max_apr_order_id = O.order_id
    JOIN gbike.rich_region R ON O.region_id = R.region_id
    JOIN gbike.rich_region E ON R.parent_id = E.region_id
    WHERE U.max_apr_order_id IS NOT NULL 
      AND E.region_name IN ('서초캠프', '광주1캠프', '평택캠프', '용인캠프', '대전1캠프')
)
-- 최종 캠프별 세그먼트 집계
SELECT 
    camp_name,
    COUNT(CASE WHEN apr_ride_count = 1 THEN 1 END) AS "1회",
    COUNT(CASE WHEN apr_ride_count BETWEEN 2 AND 3 THEN 1 END) AS "2~3회",
    COUNT(CASE WHEN apr_ride_count BETWEEN 4 AND 9 THEN 1 END) AS "4~9회",
    COUNT(CASE WHEN apr_ride_count BETWEEN 10 AND 29 THEN 1 END) AS "10~29회",
    COUNT(CASE WHEN apr_ride_count >= 30 THEN 1 END) AS "30회 이상",
    COUNT(
        CASE 
            WHEN apr_ride_count >= 1 
             AND march_ride_count > 0 -- 3월에 1번이라도 탄 경우 (M.march_count IS NOT NULL 완벽 대체)
             AND apr_ride_count < march_ride_count * 0.5 
            THEN 1 
        END
    ) AS "3월 대비 50% 미만 유저"
FROM target_users
GROUP BY camp_name
ORDER BY camp_name
;

# 1,2월 마지막 탑승 이력이 서초캠프 등 4개 캠프 고객 중에서
# 3,4월 탑승 이력이 없는 회원 수
SELECT
    E.region_name AS camp_name,
    COUNT(U.user_id) AS no_mar_apr_ride_users
FROM gbike.rich_orders O
-- 유저의 절대적인 마지막 탑승 건(latest_order_id)과 현재 확인 중인 1~2월 주문(order_id)이 일치하는지 확인
JOIN gbike.rich_user U
    ON O.user_id = U.user_id
   AND O.order_id = U.latest_order_id
JOIN gbike.rich_region R
    ON O.region_id = R.region_id
JOIN gbike.rich_region E
    ON R.parent_id = E.region_id
WHERE O.add_time >= UNIX_TIMESTAMP('2026-01-01 00:00:00') - 32400
  AND O.add_time < UNIX_TIMESTAMP('2026-03-01 00:00:00') - 32400
  AND O.order_state = 2 -- 유효 탑승 건만
  AND E.region_name IN ('서초캠프', '광주1캠프', '평택캠프', '용인캠프')
GROUP BY E.region_name;


select max(region_id) as max_region_id
from gbike.rich_region
;


select
        # count(*) as cnt
        '신규기기' as `구분`,region_name,count(*) as `할당대수`
from gbike.rich_bicycle
where 1=1
